files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --accent: #0f3460;
  --text: #f1f1f1;
  --text-muted: #a0a0b0;
  --border: #2a2a4a;
  --bought: #6b6b8b;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  background-image: linear-gradient(45deg, var(--accent) 25%, transparent 25%),
                    linear-gradient(-45deg, var(--accent) 25%, transparent 25%);
  background-size: 20px 20px;
  background-position: 0 0, 10px 10px;
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
  padding: 24px;
  width: 100%;
  max-width: 520px;
}

header {
  margin-bottom: 24px;
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 3px 3px 0 var(--accent);
  margin-bottom: 8px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.add-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 24px;
  align-items: flex-end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1 1 120px;
}

.field label {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-transform: uppercase;
}

.field input {
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px;
  outline: none;
  width: 100%;
}

.field input:focus-visible {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

.quantity-field {
  flex: 0 0 80px;
}

.btn {
  background: var(--primary);
  color: var(--text);
  border: 3px solid var(--border);
  font-family: var(--font);
  font-size: 1rem;
  font-weight: bold;
  padding: 10px 20px;
  cursor: pointer;
  text-transform: uppercase;
  box-shadow: 4px 4px 0 var(--accent);
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
}

.btn:hover {
  background: var(--primary-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--accent);
}

.btn:disabled {
  background: var(--bought);
  cursor: not-allowed;
  box-shadow: 4px 4px 0 var(--border);
  opacity: 0.6;
}

.btn.secondary {
  background: var(--accent);
  box-shadow: 4px 4px 0 var(--border);
}

.btn.secondary:hover:not(:disabled) {
  background: #1a4a7a;
}

.shopping-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
  min-height: 40px;
}

.shopping-list:empty::after {
  content: 'No items yet. Add something!';
  color: var(--text-muted);
  text-align: center;
  padding: 16px;
  font-style: italic;
}

.list-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg);
  border: 3px solid var(--border);
  padding: 10px 12px;
}

.list-item.bought {
  opacity: 0.7;
  border-color: var(--bought);
}

.list-item.bought .item-text {
  text-decoration: line-through;
  color: var(--bought);
}

.list-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--primary);
  cursor: pointer;
  flex-shrink: 0;
}

.list-item input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.item-text {
  flex: 1;
  word-break: break-word;
}

.item-qty {
  background: var(--accent);
  color: var(--text);
  font-weight: bold;
  padding: 2px 8px;
  border: 2px solid var(--border);
  font-size: 0.9rem;
  flex-shrink: 0;
}

.footer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  border-top: 3px solid var(--border);
  padding-top: 16px;
}

.remaining {
  font-size: 0.95rem;
  color: var(--text-muted);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .add-form {
    flex-direction: column;
    align-items: stretch;
  }
  .quantity-field {
    flex: 1 1 auto;
  }
  .btn {
    width: 100%;
  }
  .footer-bar {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
}

(function () {
  'use strict';

  var form = document.getElementById('add-form');
  var nameInput = document.getElementById('item-name');
  var qtyInput = document.getElementById('item-qty');
  var list = document.getElementById('shopping-list');
  var remainingEl = document.getElementById('remaining-count');
  var clearBtn = document.getElementById('clear-bought');

  var items = [];
  var nextId = 1;

  function updateUI() {
    // Reorder: unbought first, bought last (stable)
    var sorted = items.slice().sort(function (a, b) {
      return (a.bought === b.bought) ? 0 : (a.bought ? 1 : -1);
    });

    list.innerHTML = '';
    sorted.forEach(function (item) {
      var li = document.createElement('li');
      li.className = 'list-item' + (item.bought ? ' bought' : '');
      li.dataset.id = item.id;

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = item.bought;
      checkbox.id = 'chk-' + item.id;
      checkbox.setAttribute('aria-label', 'Mark ' + item.name + ' as bought');
      checkbox.addEventListener('change', function () {
        toggleBought(item.id);
      });

      var label = document.createElement('label');
      label.htmlFor = checkbox.id;
      label.className = 'item-text';
      label.textContent = item.name;

      var qty = document.createElement('span');
      qty.className = 'item-qty';
      qty.textContent = 'x' + item.qty;

      li.appendChild(checkbox);
      li.appendChild(label);
      li.appendChild(qty);
      list.appendChild(li);
    });

    var remaining = items.filter(function (i) { return !i.bought; }).length;
    remainingEl.textContent = remaining + (remaining === 1 ? ' item remaining' : ' items remaining');

    var hasBought = items.some(function (i) { return i.bought; });
    clearBtn.disabled = !hasBought;
  }

  function addItem(name, qty) {
    items.push({ id: nextId++, name: name, qty: qty, bought: false });
    updateUI();
  }

  function toggleBought(id) {
    items.forEach(function (item) {
      if (item.id === id) {
        item.bought = !item.bought;
      }
    });
    updateUI();
  }

  function clearBought() {
    items = items.filter(function (item) { return !item.bought; });
    updateUI();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var name = nameInput.value.trim();
    var qty = parseInt(qtyInput.value, 10);
    if (!name) {
      nameInput.focus();
      return;
    }
    if (isNaN(qty) || qty < 1) {
      qty = 1;
      qtyInput.value = '1';
    }
    addItem(name, qty);
    nameInput.value = '';
    qtyInput.value = '1';
    nameInput.focus();
  });

  clearBtn.addEventListener('click', clearBought);

  updateUI();
})();
